
const val=id=>{const e=document.getElementById(id);return e?e.value.trim():''};
const upcoming=()=>{const t0=iso(new Date());return FEST.filter(f=>f.d>=t0).sort((a,b)=>a.d.localeCompare(b.d))};
const daysTo=s=>Math.max(0,Math.ceil((dt(s)-new Date())/864e5));
const itemOf=id=>KITS.find(k=>k.id===id)||PRASAD.find(k=>k.id===id);
function recommend(q){const w=q.toLowerCase().split(/[^a-z]+/).filter(x=>x.length>2);if(!w.length)return[];
 return PUJAS.map(p=>({p,s:w.reduce((a,x)=>a+(p.tags.split(' ').some(tg=>tg===x||(x.length>4&&tg.startsWith(x.slice(0,5))))?2:0)+(p.n.toLowerCase().includes(x)?3:0),0)})).filter(x=>x.s>0).sort((a,b)=>b.s-a.s||b.p.pop-a.p.pop).slice(0,3).map(x=>x.p)}
function recCards(list){return list.map(p=>'<div class="card mt" style="padding:12px"><div class="row sp" style="flex-wrap:nowrap"><div><b>'+p.ic+' '+esc(p.n)+'</b><div class="sm mut">'+p.dur+' min, from '+inr(p.price*.7)+' online / '+inr(p.price)+' at home</div></div><a class="btn s" href="#/book/'+p.id+'">Book</a></div><div class="sm mut mt">Kit: '+esc(KITS.find(k=>k.id===p.kit).n)+' ('+inr(KITS.find(k=>k.id===p.kit).p)+')</div></div>').join('')}
function guide(q){
 const l=q.toLowerCase();
 if(/kundli|kundali|horoscope|muhurat|muhurta|panchang|rashi|dosh/.test(l))return'Generate your full <a href="#/kundali"><b>Kundali</b></a> — enter birth details, see planetary positions, traditional dosh analysis with explanations, and matching sevas. For your exact muhurat, your pandit confirms the best time for your city.';
 if(/cancel|refund/.test(l))return'Refund policy: 100% more than 48 hours before the puja, 75% between 24 and 48 hours, 50% within 24 hours. Cancel from <a href="#/account"><b>My bookings</b></a>.';
 if(/samagri|kit|material/.test(l))return'Browse <a href="#/samagri"><b>samagri kits</b></a>. You can order a kit alone or add one while booking a puja.';
 if(/price|cost|charge|fee/.test(l)&&!recommend(q).length)return'Prices start around '+inr(1260)+' for an online Ganesh puja. Every booking shows a full price breakdown before payment.';
 const f=FEST.find(f=>l.split(/[^a-z]+/).some(x=>x.length>3&&f.n.toLowerCase().includes(x)))||(/festival|next|upcoming/.test(l)?upcoming()[0]:null);
 if(f){return'<b>'+esc(f.n)+'</b> falls around '+fmtD(f.d)+' ('+daysTo(f.d)+' days away). '+esc(f.t)+' Suggested pujas:'+recCards(f.p.map(PU))+'<div class="sm mut mt">Dates are indicative. Confirm with your pandit.</div>'}
 const r=recommend(q);
 if(r.length)return'Based on what you shared, these pujas may suit you:'+recCards(r);
 return'I can suggest a puja from your sankalp, explain a festival, or help with booking. Try "I want peace and prosperity in my family" or "What is needed for Diwali?"';
}
function sankalpOut(q){const r=recommend(q).slice(0,2);return r.length?r.map(p=>'<div class="row sp mt" style="flex-wrap:nowrap"><div><b>'+p.ic+' '+esc(p.n)+'</b><div class="sm mut">'+p.dur+' min, from '+inr(p.price*.7)+'</div></div><a class="btn s" href="#/book/'+p.id+'">Book</a></div>').join(''):'<p class="sm mut mt">Try words like peace, health, new home or business.</p>'}

function home(){
 const pop=PUJAS.filter(p=>p.pop).slice(0,6),up=upcoming().slice(0,3);
 const intents=[['Peace at home','peace family harmony'],['Prosperity','wealth prosperity money'],['New home','new home house'],['Health','health recovery'],['New business','business shop opening'],['Exams','exam student education']];
 return'<section class="hero">'+mandala()+'<div class="wrap"><div><h1>'+t('h1a')+'<br>'+t('h1b')+'</h1><p class="lead">'+t('lead')+'</p><div class="sbox"><input id="hq" placeholder="'+t('search')+'" aria-label="Search pujas"><button class="btn gold" data-act="hsearch">'+t('find')+'</button></div><div class="strip"><span>KYC-verified pandits</span><span>Prices shown before you pay</span><span>Samagri at your door</span><span>Prasad after the puja</span></div></div>'+
 '<div class="sankalp">'+diya()+'<h3>'+t('sk')+'</h3><p class="sm mut c mt">Pick what you are seeking. We suggest a puja.</p><div class="row mt" style="justify-content:center">'+intents.map(i=>'<button class="chip" data-act="intent" data-q="'+i[1]+'">'+i[0]+'</button>').join('')+'</div><div id="skout" aria-live="polite"></div></div></div></section>'+
 '<section class="sec"><div class="wrap"><div class="shead"><div><h2>From sankalp to prasad</h2><p>One booking carries the whole puja: the pandit, the samagri, the ritual and the prasad afterwards.</p></div></div><div class="jr"><div><span class="n">1</span><b>Choose the puja</b><span class="sm mut">By festival, life event or need</span></div><div><span class="n">2</span><b>Book a verified pandit</b><span class="sm mut">Pick a date, place and pandit</span></div><div><span class="n">3</span><b>Samagri delivered</b><span class="sm mut">Packed for your puja</span></div><div><span class="n">4</span><b>Puja is conducted</b><span class="sm mut">At home, online or at a temple</span></div><div><span class="n">5</span><b>Photos and video</b><span class="sm mut">With a digital confirmation</span></div><div><span class="n">6</span><b>Prasad arrives</b><span class="sm mut">Dispatched and tracked</span></div></div></div></section>'+
 '<section class="sec alt"><div class="wrap"><div class="shead"><div><h2>Four ways to have a puja</h2></div></div><div class="grid g4">'+Object.entries(MODES).map(([k,m])=>'<a class="card" href="#/pujas?mode='+k+'"><div style="font-size:2rem">'+m.i+'</div><h3 class="mt">'+m.n+'</h3><p class="sm mut">'+m.d+'</p></a>').join('')+'</div></div></section>'+
 '<section class="sec"><div class="wrap"><div class="shead"><div><h2>Popular pujas</h2><p>Priced upfront. Online pujas cost less; home and customized pujas include more of the pandit\'s time.</p></div><a class="btn sec" href="#/pujas">All pujas</a></div><div class="grid g3">'+pop.map(pujaCard).join('')+'</div></div></section>'+
 '<section class="sec dk"><div class="wrap"><div class="shead"><div><h2>Coming up in the calendar</h2><p>Every festival links to the pujas usually done that day, the pandits available and the samagri needed.</p></div><a class="btn gold" href="#/festivals">Festival calendar</a></div><div class="grid g3">'+up.map(f=>'<div class="card" style="background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.18);color:#fff"><div class="b" style="font-size:2.4rem;font-family:Yatra One">'+daysTo(f.d)+' <span style="font-size:1rem;font-family:Hind">days</span></div><h3>'+f.n+'</h3><p class="sm" style="opacity:.8">'+fmtD(f.d)+'</p><div class="row mt">'+f.p.map(id=>'<a class="chip" href="#/book/'+id+'" style="color:#10201f">'+PU(id).n+'</a>').join('')+'</div></div>').join('')+'</div></div></section>'+
 '<section class="sec"><div class="wrap"><div class="shead"><div><h2>Trust is built into every step</h2></div></div><div class="grid g3"><div class="card"><h3>Pandit KYC and verified badge</h3><p class="sm mut mt">ID and document checks before a pandit gets bookings. Ratings are only from completed pujas.</p></div><div class="card"><h3>Transparent pricing</h3><p class="sm mut mt">Service, samagri, fees and GST are listed line by line, with a digital invoice.</p></div><div class="card"><h3>Secure payments and audit trail</h3><p class="sm mut mt">Every booking keeps a timeline of changes, and support can see it if you raise a complaint.</p></div><div class="card"><h3>Clear refund policy</h3><p class="sm mut mt">Cancel from your account and track the refund status.</p></div><div class="card"><h3>Privacy controls</h3><p class="sm mut mt">Pandits see only what they need: name, address and puja details for confirmed bookings.</p></div><div class="card"><h3>Quality monitoring</h3><p class="sm mut mt">Reviews are moderated and low ratings are followed up by the operations team.</p></div></div></div></section>'+
 '<section class="sec alt"><div class="wrap"><div class="shead"><div><h2>Pandits you can book</h2></div><a class="btn sec" href="#/pandits">All pandits</a></div><div class="grid g4">'+db.pandits.filter(p=>p.st==='verified'&&p.feat).concat(db.pandits.filter(p=>p.st==='verified'&&!p.feat).slice(0,2)).map(panditCard).join('')+'</div></div></section>'+
 '<section class="sec"><div class="wrap grid g2"><div class="card"><h2 style="font-size:1.8rem">Samagri, packed for the puja</h2><p class="mut mt">Ready kits for Lakshmi, Satyanarayan, Griha Pravesh and more. Same-day or scheduled delivery.</p><a class="btn mt" href="#/samagri">Shop samagri</a></div><div class="card"><h2 style="font-size:1.8rem">Prasad to your door</h2><p class="mut mt">Laddu, peda, panchmeva and temple prasad, dispatched after your puja is completed.</p><a class="btn mt" href="#/prasad">See prasad</a></div></div></section>'+
 '<section class="sec alt"><div class="wrap grid g2"><div><h2>DaivikPooja Plus and Rewards</h2><p class="mut mt">Members pay no convenience fee, get free delivery and earn double reward points. Every booking earns points you can use on your next puja.</p><div class="row mt"><a class="btn" href="#/plus">See Plus</a><a class="btn sec" href="#/rewards">How rewards work</a></div></div><div><h2>Puja for your organisation</h2><p class="mut mt">Office openings, bhoomi pujan, festival events and prasad gifting, with monthly billing and a dedicated account manager.</p><a class="btn sec mt" href="#/corporate">Corporate pujas</a></div></div></section>'+
 '<section class="sec"><div class="wrap grid g2"><div><h2>What families say</h2><div class="col mt">'+TESTI.map(x=>'<div class="qt"><p>'+esc(x[0])+'</p><div class="sm mut">'+esc(x[1])+'</div></div>').join('')+'</div></div><div><h2>Questions</h2><div class="mt">'+FAQ.map(f=>'<details><summary>'+f[0]+'</summary><p>'+f[1]+'</p></details>').join('')+'</div></div></div></section>';
}

function pujaFilterHtml(f){const fs=upcoming();return'<div class="card flat"><div class="frm"><label class="f">Search<input data-in="pf" data-k="q" value="'+esc(f.q)+'" placeholder="Puja, deity or need"></label><label class="f">Category<select data-in="pf" data-k="cat"><option value="">All</option>'+CATS.map(c=>'<option'+(f.cat===c?' selected':'')+'>'+c+'</option>').join('')+'</select></label><label class="f">Puja type<select data-in="pf" data-k="mode"><option value="">Any</option>'+Object.entries(MODES).map(([k,m])=>'<option value="'+k+'"'+(f.mode===k?' selected':'')+'>'+m.n+'</option>').join('')+'</select></label><label class="f">Festival<select data-in="pf" data-k="fest"><option value="">Any</option>'+FEST.map(x=>'<option value="'+x.id+'"'+(f.fest===x.id?' selected':'')+'>'+x.n+'</option>').join('')+'</select></label><label class="f">Sort by<select data-in="pf" data-k="sort"><option value="pop"'+(f.sort==='pop'?' selected':'')+'>Popular</option><option value="lo"'+(f.sort==='lo'?' selected':'')+'>Price, low to high</option><option value="hi"'+(f.sort==='hi'?' selected':'')+'>Price, high to low</option><option value="dur"'+(f.sort==='dur'?' selected':'')+'>Shortest duration</option></select></label></div></div>'}
function pujaResults(){const f=PAGE.f;let l=PUJAS.filter(p=>!p.hidden);
 if(f.q){const w=f.q.toLowerCase();l=l.filter(p=>(p.n+p.h+p.deity+p.tags+p.ben).toLowerCase().includes(w)||recommend(f.q).some(r=>r.id===p.id))}
 if(f.cat)l=l.filter(p=>p.cat===f.cat);if(f.mode)l=l.filter(p=>modesFor(p).includes(f.mode));if(f.fest){const x=FEST.find(z=>z.id===f.fest);l=l.filter(p=>x&&x.p.includes(p.id))}
 l=l.slice().sort((a,b)=>f.sort==='lo'?a.price-b.price:f.sort==='hi'?b.price-a.price:f.sort==='dur'?a.dur-b.dur:b.pop-a.pop);
 return'<p class="sm mut mb">'+l.length+' pujas found</p><div class="grid g3">'+(l.length?l.map(pujaCard).join(''):'<div class="card">No pujas match these filters. Clear a filter, or ask the DaivikPooja Guide to suggest one.</div>')+'</div>'}
function pujas(r){PAGE.f=Object.assign({q:'',cat:'',mode:'',fest:'',sort:'pop'},r.q);return'<div class="page"><div class="wrap"><h1>Puja catalogue</h1><p class="mut mb">Search by need, browse by category, festival or life event, and compare prices.</p>'+pujaFilterHtml(PAGE.f)+'<div id="pl" class="mt">'+pujaResults()+'</div></div></div>'}

function pujaDetail(r){const p=PU(r.arg);if(!p)return nf();const pds=db.pandits.filter(x=>x.st==='verified'&&x.spec.includes(p.id)).slice(0,4);const kit=KITS.find(k=>k.id===p.kit);
 const days=[...Array(7)].map((_,i)=>addDays(i+1));
 /* Photo gallery state + async load (approved+published only). Fired before the
    return so it actually runs; the container #pujaPhotos exists once render lands. */
 PAGE.gal={pujaId:p.id,cat:'all',offset:0,items:[],total:0};
 api('/pujas/'+p.id+'/photos?limit=8&page=1').then(x=>{const el=$('#pujaPhotos');if(!el||PAGE.gal.pujaId!==p.id)return;PAGE.gal.items=x.photos;PAGE.gal.total=x.total;PAGE.gal.offset=x.photos.length;
  if(x.photos.length)el.innerHTML='<h2 class="mt2 mb">Photo gallery</h2><div class="tabs mb">'+[['all','All'],['puja','Puja'],['ritual','Ritual'],['temple','Temple'],['seva','Previous seva']].map(c=>'<button data-act="galcat" data-v="'+c[0]+'">'+c[1]+'</button>').join('')+'</div><div id="galgrid" class="row" style="flex-wrap:wrap">'+galCards(x.photos)+'</div>'+(x.nextOffset!=null?'<div class="c mt"><button class="btn s ghost" data-act="galmore">Load more</button></div>':'')}).catch(()=>{});
 return'<div class="page"><div class="wrap"><a class="sm mut" href="#/pujas">All pujas</a><div class="grid g2 mt"><div><div class="row"><span style="font-size:3rem">'+p.ic+'</span><div><span class="vt">'+p.cat+'</span><h1 style="margin:0">'+esc(p.n)+'</h1><div class="mut">'+p.h+', '+esc(p.deity)+'</div></div></div><p class="mt">'+esc(p.ben)+' The pandit takes your sankalp with your name and gotra, invokes the deity, performs the main worship, and concludes with aarti and prasad.</p><div class="row mt"><span class="badge">'+p.dur+' minutes</span>'+modesFor(p).map(m=>'<span class="badge info">'+MODES[m].n+'</span>').join('')+'</div><div class="row mt2"><a class="btn" href="#/book/'+p.id+'">'+t('book')+'</a><button class="btn sec" data-act="askp" data-id="'+p.id+'">Ask the guide</button></div></div><div class="card"><h3>Pricing by puja type</h3><div class="tw mt"><table><tbody>'+modesFor(p).map(m=>'<tr><td>'+MODES[m].i+' '+MODES[m].n+'</td><td class="b">'+inr(p.price*MODES[m].f)+'</td></tr>').join('')+'</tbody></table></div><p class="sm mut mt">Base price for a standard pandit. Senior pandits are priced slightly higher. Convenience fee and GST are added at checkout.</p></div></div>'+
 '<div class="grid g2 mt2"><div class="card"><h3>Required samagri</h3><ul class="mt" style="padding-left:20px">'+p.sam.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul><p class="sm mut mt">Or add the <b>'+esc(kit.n)+'</b> ('+inr(kit.p)+') during booking and we deliver it.</p></div><div class="card"><h3>Available dates, next 7 days</h3><div class="col mt">'+days.map(d=>{const n=db.pandits.filter(x=>x.spec.includes(p.id)&&free(x,d)).length;return'<div class="row sp"><span>'+dt(d).toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'})+'</span><span class="'+(n?'':'mut')+'">'+(n?n+' pandit'+(n>1?'s':'')+' free':'Fully booked')+'</span></div>'}).join('')+'</div><p class="sm mut mt">Time slots: '+SLOTS.join(', ')+'</p></div></div>'+
 '<h2 class="mt2 mb">Pandits for this puja</h2><div class="grid g4">'+(pds.length?pds.map(panditCard).join(''):'<div class="card">No pandit listed yet. Choose auto-assign while booking.</div>')+ '</div><div id="pujaPhotos"></div></div></div>';
}
const galCards=ph=>ph.map((p,i)=>'<figure class="card flat" style="width:200px;padding:8px;margin:4px"><a href="javascript:void(0)" data-act="galopen" data-i="'+PAGE.gal.items.indexOf(p)+'"><picture>'+(p.thumbWebp?'<source type="image/webp" srcset="'+mediaUrl(p.thumbWebp)+'">':'')+'<img src="'+mediaUrl(p.thumb||p.url)+'" alt="'+esc(p.altText||'Puja photo')+'" loading="lazy" decoding="async" style="width:100%;height:140px;object-fit:cover;border-radius:10px;background:#eee"></picture></a>'+(p.credit?'<figcaption class="sm mut mt">'+esc(p.credit)+(p.license?' · '+esc(p.license):'')+'</figcaption>':'')+'</figure>');

function panditsPage(){PAGE.pf={city:'',lang:'',puja:''};const langs=[...new Set(db.pandits.flatMap(p=>p.langs))].sort();
 return'<div class="page"><div class="wrap"><h1>Verified pandits</h1><p class="mut mb">Every pandit below has completed mobile OTP verification and ID and document KYC.</p><div class="card flat"><div class="frm"><label class="f">City<select data-in="pdf" data-k="city"><option value="">All</option>'+CITIES.map(c=>'<option>'+c+'</option>').join('')+'</select></label><label class="f">Language<select data-in="pdf" data-k="lang"><option value="">Any</option>'+langs.map(c=>'<option>'+c+'</option>').join('')+'</select></label><label class="f">Puja expertise<select data-in="pdf" data-k="puja"><option value="">Any</option>'+PUJAS.map(c=>'<option value="'+c.id+'">'+c.n+'</option>').join('')+'</select></label></div></div><div id="pdl" class="grid g3 mt">'+panditList()+'</div></div></div>'}
function panditList(){const f=PAGE.pf;const l=db.pandits.filter(p=>p.st==='verified'&&(!f.city||p.city===f.city)&&(!f.lang||p.langs.includes(f.lang))&&(!f.puja||p.spec.includes(f.puja))).sort((a,b)=>b.rating-a.rating);return l.length?l.map(panditCard).join(''):'<div class="card">No pandit matches. Try another city or language.</div>'}
function panditProfile(r){const p=PD(r.arg);if(!p)return nf();const revs=db.reviews.filter(x=>x.pid===p.id);
 return'<div class="page"><div class="wrap"><a class="sm mut" href="#/pandits">All pandits</a><div class="card mt"><div class="row" style="flex-wrap:nowrap">'+av(p,76)+'<div><h1 style="margin:0;font-size:2rem">'+esc(p.n)+'</h1><div class="mut">'+esc(p.city)+', '+p.exp+' years of experience</div><div>'+(p.rating?stars(p.rating)+' '+p.rating+' from '+p.rev+' reviews, '+p.done+' pujas':'New pandit')+(p.qa!=null?' · <span class="vt">QA '+p.qa+'/5</span>':'')+'</div><span class="vt">✔ KYC verified</span></div></div>'+(p.gotra||p.veda||p.quals?'<div class="card mt"><div class="grid g3">'+(p.gotra?'<div><b>Gotra</b><br>'+esc(p.gotra)+'</div>':'')+(p.veda?'<div><b>Tradition</b><br>'+esc(p.veda)+'</div>':'')+(p.quals?'<div><b>Qualifications</b><br>'+esc(p.quals)+'</div>':'')+'</div></div>':'')+'<div class="card mt"><p>'+(p.bio?esc(p.bio):'')+'</p><p class="mt"><b>Languages:</b> '+p.langs.join(', ')+'</p></div><h2 class="mt2 mb">Book '+esc(p.n.split(' ')[0]+' '+p.n.split(' ')[1])+' for</h2><div class="row">'+p.spec.map(id=>'<a class="chip" href="#/book/'+id+'?pandit='+p.id+'">'+PU(id).ic+' '+PU(id).n+'</a>').join('')+'</div><h2 class="mt2 mb">Reviews</h2>'+(revs.length?'<div class="grid g2">'+revs.map(x=>'<div class="card">'+stars(x.r)+'<p class="mt">'+esc(x.t)+'</p><div class="sm mut">'+esc(x.by)+' for '+(PU(x.puja)?PU(x.puja).n:'a puja')+'</div></div>').join('')+'</div>':'<div class="card">No reviews yet.</div>')+'</div></div>'}

function temples(){return'<div class="page"><div class="wrap"><h1>Temple pujas</h1><p class="mut mb">Can\'t travel? A pandit performs the puja at the temple in your name and you receive photos, a video and prasad.</p><div class="note mb">Sample listing. Temple partnerships and offerings are illustrative and would be finalised with each temple.</div><div class="grid g3">'+TEMPLES.map(x=>'<article class="card">'+(x.photo?'<img src="'+esc(mediaUrl(x.photo))+'" alt="'+esc(x.n)+'" loading="lazy" style="width:100%;height:130px;object-fit:cover;border-radius:10px">':'<div class="c" style="font-size:2.4rem">'+x.ic+'</div>')+'<div class="row sp mt"><h3>'+x.n+'</h3><span class="badge">'+x.city+'</span></div>'+(x.timings?'<p class="sm mut" style="margin:4px 0 0">🕙 '+esc(x.timings)+'</p>':'')+'<p class="sm mut mt">'+x.d+'</p><div class="row mt">'+x.pujas.map(id=>'<a class="chip" href="#/book/'+id+'?mode=temple&temple='+x.id+'">'+PU(id).n+'</a>').join('')+'</div></article>').join('')+'</div></div></div>'}
function samagriPage(){return'<div class="page"><div class="wrap"><h1>Samagri kits</h1><p class="mut mb">Packed by puja, delivered before your date. Free delivery over '+inr(999)+' and for Plus members.</p><div class="grid g3">'+KITS.filter(k=>k.active!==0).map(kitCard).join('')+'</div></div></div>'}
function prasadPage(){return'<div class="page"><div class="wrap"><h1>Prasad</h1><p class="mut mb">Order alone or add to a puja booking. Prasad from a puja is dispatched after completion.</p><div class="grid g3">'+PRASAD.filter(k=>k.active!==0).map(k=>'<article class="card"><div class="row sp"><span style="font-size:2rem">'+k.ic+'</span><b>'+inr(k.p)+'</b></div><h3 class="mt">'+k.n+'</h3><p class="sm mut">'+k.d+'</p><button class="btn s mt" data-act="cadd" data-id="'+k.id+'">Add to cart</button></article>').join('')+'</div></div></div>'}

var CART_DISC={code:'',amt:0};
function cartModal(){
 if(!cart.length){modal('<h2>Your cart</h2><p class="mut mt">Nothing here yet. Add a samagri kit or prasad.</p><div class="row mt"><a class="btn" href="#/samagri" data-act="close">Samagri</a><a class="btn sec" href="#/prasad" data-act="close">Prasad</a></div>');return}
 const u=me(),sub=cart.reduce((a,c)=>a+itemOf(c.k).p*c.q,0);
 /* Phase 14: an ALL-scope coupon checked in the modal is applied to the total here. */
 const disc=(CART_DISC.code&&CART_DISC.amt>0&&CART_DISC.amt<=sub)?CART_DISC.amt:0,after=sub-disc,del=after>=999||(u&&u.plus)?0:49;
 modal('<h2>Your cart</h2><div class="col mt">'+cart.map(c=>{const i=itemOf(c.k);return'<div class="row sp"><span>'+i.ic+' '+esc(i.n)+'</span><span class="row"><button class="btn s ghost" data-act="cq" data-id="'+c.k+'" data-d="-1" aria-label="Less">-</button><b>'+c.q+'</b><button class="btn s ghost" data-act="cq" data-id="'+c.k+'" data-d="1" aria-label="More">+</button><span style="min-width:70px;text-align:right">'+inr(i.p*c.q)+'</span></span></div>'}).join('')+'</div><div class="row sp mt"><span>Delivery</span><span>'+(del?inr(del):'Free')+'</span></div>'+(disc?'<div class="row sp mt"><span>Coupon <b>'+CART_DISC.code+'</b></span><span style="color:var(--ok,#1e8449)">-'+inr(disc)+'</span></div>':'')+'<div class="row sp b mt"><span>Total</span><span>'+inr(after+del)+'</span></div><div class="frm mt"><label class="f">Coupon code<input id="ccpn" value="'+CART_DISC.code+'" placeholder="ALL-scope coupons apply to the cart"></label><div class="row mt"><button class="btn s ghost" data-act="cc-check">Check</button><span id="ccout" class="sm mut"></span></div></div><div class="frm mt"><label class="f">Delivery address<input id="cad" value="'+esc(u&&u.addr[0]?u.addr[0].line:'')+'"></label><label class="f">City<select id="cct">'+CITIES.map(c=>'<option'+(u&&u.addr[0]&&u.addr[0].city===c?' selected':'')+'>'+c+'</option>').join('')+'</select></label></div><button class="btn blk mt" data-act="corder">Place order for '+inr(after+del)+' (pay on delivery)</button>');
}

function festivalsPage(r){const now=new Date(),ym=PAGE.cal||(PAGE.cal={y:now.getFullYear(),m:now.getMonth()});const first=new Date(ym.y,ym.m,1),n=new Date(ym.y,ym.m+1,0).getDate(),lead=first.getDay();
 let cells='';['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach(d=>cells+='<div class="h">'+d+'</div>');for(let i=0;i<lead;i++)cells+='<div></div>';
 for(let d=1;d<=n;d++){const s=ym.y+'-'+String(ym.m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');const fs=FEST.filter(f=>f.d===s);cells+='<div class="d'+(s===iso(now)?' t':'')+'"><b>'+d+'</b>'+fs.map(f=>'<small>'+f.n+'</small>').join('')+'</div>'}
 return'<div class="page"><div class="wrap"><h1>Festival calendar</h1><p class="mut mb">Festival, recommended puja, pandit, samagri, booking: all connected.</p><div class="note mb">Dates are indicative and can differ by region and Panchang. Your pandit will confirm the exact tithi and muhurat.</div><div class="grid g2" style="grid-template-columns:1.2fr 1fr;align-items:start"><div class="card"><div class="row sp mb"><button class="btn s ghost" data-act="calm" data-d="-1">Previous</button><h3 id="calt">'+first.toLocaleDateString('en-IN',{month:'long',year:'numeric'})+'</h3><button class="btn s ghost" data-act="calm" data-d="1">Next</button></div><div class="cal" id="calg">'+cells+'</div></div><div class="col">'+upcoming().slice(0,6).map(f=>'<div class="card"><div class="row sp"><h3>'+f.n+'</h3><span class="badge warn">'+daysTo(f.d)+' days</span></div><div class="sm mut">'+fmtD(f.d)+'. '+f.t+'</div><div class="row mt">'+f.p.map(id=>'<a class="chip" href="#/book/'+id+'">'+PU(id).ic+' '+PU(id).n+'</a>').join('')+'</div></div>').join('')+'</div></div><h2 class="mt2 mb">Every month</h2><div class="grid g4">'+RECUR.map(x=>'<div class="card"><h3>'+x.n+'</h3><p class="sm mut">'+x.t+'</p><a class="btn s sec mt" href="#/puja/'+x.p+'">'+PU(x.p).n+'</a></div>').join('')+'</div></div></div>'}
function calRender(){const g=PAGE.cal,now=new Date();const first=new Date(g.y,g.m,1),n=new Date(g.y,g.m+1,0).getDate();let cells='';['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach(d=>cells+='<div class="h">'+d+'</div>');for(let i=0;i<first.getDay();i++)cells+='<div></div>';for(let d=1;d<=n;d++){const s=g.y+'-'+String(g.m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');cells+='<div class="d'+(s===iso(now)?' t':'')+'"><b>'+d+'</b>'+FEST.filter(f=>f.d===s).map(f=>'<small>'+f.n+'</small>').join('')+'</div>'}$('#calg').innerHTML=cells;$('#calt').textContent=first.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}

